/**
 * Avatar. A disc sunk into the chassis: the image
 * sits in a well, initials are engraved into the plastic. Composes
 * var(--echo-*).
 */
.echo-avatar {
  /* Not overflow:hidden — the presence LED sits ON the rim, half outside.
     The image clips itself to the disc instead. */
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border-radius: var(--echo-radius-full);
  background: var(--echo-drawn-glass, linear-gradient(160deg, var(--echo-well) 0%, var(--echo-lcd) 100%));
  box-shadow:
    inset 0 2px 5px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.8 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1))),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
}

/*
 * The disc is in rem, like the type it holds: identical at a default
 * text size, and it grows with the reader's instead of clipping the initials.
 */
/* xs: inline with a line of text, a mention or a byline. */
.echo-avatar[data-size="xs"] {
  width: 1.25rem;
  height: 1.25rem;
  font-size: var(--echo-text-3xs);
}
.echo-avatar[data-size="sm"] {
  width: 1.5rem;
  height: 1.5rem;
  font-size: var(--echo-text-3xs);
}

.echo-avatar[data-size="md"] {
  width: 2.25rem;
  height: 2.25rem;
  font-size: var(--echo-text-xs);
}

.echo-avatar[data-size="lg"] {
  width: 3.25rem;
  height: 3.25rem;
  font-size: var(--echo-text-lg);
}
/* xl: a profile header. */
.echo-avatar[data-size="xl"] {
  width: 5rem;
  height: 5rem;
  font-size: var(--echo-text-2xl);
}

.echo-avatar__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  border-radius: inherit;
}

/* Engraved, not printed: dark ink with a light lower bevel. */
.echo-avatar__initials {
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-wide, 0.06em);
  line-height: var(--echo-leading-none, 1);
  color: var(--echo-text-dim);
  text-shadow: 0 1px 0 rgb(255 255 255 / calc(0.08 * var(--echo-gloss, 1)));
}

/*
 * The presence LED (2026-09-18). A socket drilled into the rim at the key
 * light's far corner: empty when idle, lit accent when live — StatusDot's
 * fill-vs-hollow rule, so the state survives greyscale and every CVD. The
 * chassis-coloured ring seats it in the plastic rather than floating it on top.
 */
.echo-avatar__led {
  position: absolute;
  inset-inline-end: 0;
  bottom: 0;
  box-sizing: border-box;
  width: 26%;
  height: 26%;
  min-width: 8px;
  min-height: 8px;
  border-radius: var(--echo-radius-full);
  background: var(--echo-well);
  border: var(--echo-border-fine, 1.5px) solid color-mix(in oklab, var(--echo-text-dim) 72%, transparent);
  box-shadow:
    0 0 0 2px var(--echo-surface),
    inset 0 1px 1.5px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.7 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 0 0 var(--echo-line-width, 0px) var(--echo-line, transparent);
  /* The LED lights and goes dark over a moment, like StatusDot's. */
  transition:
    background-color var(--echo-duration-tick) ease-out,
    border-color var(--echo-duration-tick) ease-out;
}
@media (prefers-reduced-motion: reduce) {
  .echo-avatar__led {
    transition: none;
  }
}

.echo-avatar[data-status="live"] .echo-avatar__led {
  background: var(--echo-accent-glow);
  border-color: var(--echo-accent-glow);
  box-shadow:
    0 0 0 2px var(--echo-surface),
    inset 0 1px 0 rgb(255 255 255 / calc(0.45 * var(--echo-gloss, 1)));
}

"use client";

/**
 * Avatar. A person or device as a molded disc: the
 * image seated in a well, or initials engraved into the plastic when there is
 * no image — or when the image fails to load, which is the case a plain <img>
 * silently gets wrong.
 *
 * A static component with no behaviour primitive underneath: the only
 * behaviour is the load-failure fallback, which is a single piece of state.
 * NOTE: @base-ui/react has since added an `avatar` primitive with the same
 * fallback semantics. Moving onto it would change the component's behaviour,
 * not just its internals, so it stays hand-built until that call is made.
 */
import { useCallback, useState } from "react";
import type { HTMLAttributes } from "react";
import "./avatar.css";

export type AvatarSize = "xs" | "sm" | "md" | "lg" | "xl";
export type AvatarStatus = "live" | "idle";

export interface AvatarProps extends Omit<HTMLAttributes<HTMLSpanElement>, "children"> {
  /** Image URL. Omit to render initials. */
  src?: string;
  /** Who or what this is. Required — it is the accessible name. */
  name: string;
  size?: AvatarSize;
  /** Override the derived initials (e.g. a device code). */
  initials?: string;
  /**
   * A presence LED seated in the rim: `live` is lit, `idle` is an empty
   * socket — StatusDot's fill-vs-hollow rule, so the state never rests on
   * colour alone. Added to the accessible name as ", live" / ", idle".
   */
  status?: AvatarStatus;
  /** Override the words announced for `status`. */
  statusLabel?: string;
}

/** First letters of the first and last words — "Ada Lovelace" → "AL". */
function deriveInitials(name: string): string {
  const words = name.trim().split(/\s+/).filter(Boolean);
  if (words.length === 0) return "?";
  const first = words[0]![0] ?? "";
  const last = words.length > 1 ? (words[words.length - 1]![0] ?? "") : "";
  return (first + last).toUpperCase();
}

export function Avatar({
  src,
  name,
  size = "md",
  initials,
  status,
  statusLabel,
  className,
  ...rest
}: AvatarProps) {
  // Keyed by URL rather than a boolean, so a new src gets a fresh attempt
  // instead of inheriting the previous one's failure.
  const [failedSrc, setFailedSrc] = useState<string | null>(null);
  const showImage = Boolean(src) && failedSrc !== src;

  /**
   * The server-rendered <img> starts loading before hydration, so a 404 can
   * fire its error event before React ever attaches onError — leaving a
   * permanently broken image and no fallback. Re-check the outcome when the
   * node attaches: complete with no intrinsic width means it failed.
   */
  const checkAlreadyFailed = useCallback(
    (node: HTMLImageElement | null) => {
      if (node && node.complete && node.naturalWidth === 0 && src) setFailedSrc(src);
    },
    [src],
  );

  return (
    <span
      className={["echo-avatar", className].filter(Boolean).join(" ")}
      data-size={size}
      data-status={status}
      role="img"
      aria-label={status ? `${name}, ${statusLabel ?? status}` : name}
      {...rest}
    >
      {showImage ? (
        <img
          className="echo-avatar__image"
          ref={checkAlreadyFailed}
          src={src}
          alt=""
          onError={() => setFailedSrc(src ?? null)}
          draggable={false}
        />
      ) : (
        <span className="echo-avatar__initials" aria-hidden="true">
          {initials ?? deriveInitials(name)}
        </span>
      )}
      {status ? <span className="echo-avatar__led" aria-hidden="true" /> : null}
    </span>
  );
}
